import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AboutPage.css";

const AboutP = [
  {
    id: 1,
    title: "Projeto 1", 
    description: "Descrição breve dos módulos",
    author: "Lucas Prado",
    views: 5,
    date: "há 21 horas",
    image: "",
  },
  {
    id: 2,
    title: "Projeto 2",
    description: "Descrição breve do Projeto 2",
    author: "Lucas Prado",
    views: 0,
    date: "há 21 horas",
    image: "",
  },
];

function expandText() {
  var fullText = document.getElementById('fullText');
  var readMore = document.getElementById('readMore');
  if (fullText.style.display === 'none') {
    fullText.style.display = 'block'; // Mostra o texto completo
    readMore.style.display = 'none'; // Esconde o botão "Continuar lendo"
  } else {
    fullText.style.display = 'none'; // Esconde o texto completo
    readMore.style.display = 'block'; // Mostra o botão "Continuar lendo"
  }
}


const AboutPage = () => {
  const [aboutViews, setaboutViews] = useState(AboutP);
  const navigate = useNavigate();

  useEffect(() => {
    const savedViews = JSON.parse(localStorage.getItem('aboutViews') || '[]');
    if (savedViews.length > 0) {
      setaboutViews(savedViews);
    }
  }, []);

  const handleClickabout = (id) => {
    setaboutViews((prevAboutP) => {
      const updatedAboutP = prevAboutP.map((about) =>
        about.id === id
          ? { ...about, views: about.views + 1 }
          : about
      );
      localStorage.setItem('aboutViews', JSON.stringify(updatedAboutP));
      return updatedAboutP;
    });

    navigate(`/AboutP/${id}`);
  };

  return (
    <div className="AboutP-page">
      <div className="name_apresentation">
        <div className="logo">
          <span className="idctec">IDC<b>TEC</b></span>
        </div>
        <div className="subtitle">
          <span>Integração Digital e <br/> Capacitação Tecnológica</span>
        </div>
      </div>
      <div className="about-label">
        <div class="about-info">
          <h1 class="about-info-title">QUEM SOMOS</h1>
          <p class="about-info-text" id="shortText">Lorem ipsum dolor sit amet consectetur adipisicing elit. Praesentium itaque, 
            similique, distinctio, quo natus dignissimos molestiae corrupti nostrum sed vel non. Facilis provident incidunt, quis 
            laboriosam temporibus rerum voluptatum dicta!</p>
          <a href="#" onclick="expandText()" id="readMore">Continuar lendo</a>
          <p class="about-info-text fullText" id="fullText" style="display:none;">
            Lorem ipsum dolor sit, amet consectetur adipisicing elit. Magni delectus perferendis numquam aliquam placeat tempora, 
            omnis nesciunt ea hic laboriosam adipisci odit voluptatem eum asperiores officiis enim unde ipsum repellendus?Lorem ipsum 
            dolor sit amet consectetur adipisicing elit. Repellat corrupti quidem, expedita aut natus nesciunt pariatur, sequi, alias 
            sit tempora ipsa? Cum sed assumenda soluta, aperiam impedit consequatur numquam ex.
          </p>
        </div>
        <div className="about-info-image">
          <img src="images/grupo.jpg" alt="Imagem nossaaa" />
        </div>
      </div>
      <div className="AboutP-container">
        {aboutViews.map((about) => (
          <div
            key={about.id}
            className="about-card"
            onClick={() => handleClickabout(about.id)}
          >
            <div className="about-image">
              {about.image ? (
                <img src={about.image} alt={about.title} />
              ) : (
                <div className="placeholder-icon">
                  <span>📘</span>
                </div>
              )}
            </div>

            <div className="about-info">
              <h2 className="about-title">{about.title}</h2>
              <p className="about-description">{about.description}</p>
              <p className="about-author">{about.author}</p>
              <div className="about-stats">
                <span>{about.views} visualizações</span>
                <span>{about.date}</span>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AboutPage;
